export function translate(value: string, language: Language): string {
  return translations[language][value] || translations[language][value.trim()] || value;
}

const LanguageContext = createContext<{ language: Language; setLanguage: (language: Language, explicit?: boolean) => void; explicitSelection: boolean } | null>(null);
export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    try { const stored = localStorage.getItem(STORAGE_KEY); return stored === "hi" || stored === "kn" || stored === "mr" ? stored : "en"; } catch { return "en"; }
  });
  const [explicitSelection, setExplicitSelection] = useState(false);
  const setLanguage = useCallback((next: Language, explicit = true) => {
    setLanguageState(next);
    if (explicit) setExplicitSelection(true);
    try { localStorage.setItem(STORAGE_KEY, next); } catch { /* Storage is optional; language still changes for this session. */ }
  }, []);
  useEffect(() => { document.documentElement.lang = language; }, [language]);
  const value = useMemo(() => ({ language, setLanguage, explicitSelection }), [language, setLanguage, explicitSelection]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}
export function useLanguage() {
  const value = useContext(LanguageContext);
  if (!value) throw new Error("useLanguage must be used inside LanguageProvider");
  return value;
}
export function TranslateContent({ children }: { children: ReactNode }) {
  const { language } = useLanguage();
  const nodeText = useRef(new WeakMap<Text, { original: string; translated: string }>()).current;
  const attributeText = useRef(new WeakMap<Element, Map<string, { original: string; translated: string }>>()).current;
  useEffect(() => {
    const apply = (root: Node) => {
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
        acceptNode(node) {
          const parent = node.parentElement;
          if (!parent || parent.closest("[data-no-translate],script,style,textarea")) return NodeFilter.FILTER_REJECT;
          return NodeFilter.FILTER_ACCEPT;
        },
      });
      let textNode: Text | null;
      while ((textNode = walker.nextNode() as Text | null)) {
        const prior = nodeText.get(textNode);
        const current = textNode.data;
        const original = prior && current === prior.translated ? prior.original : current;
        const translated = translate(original, language);
        nodeText.set(textNode, { original, translated });
        if (current !== translated) textNode.data = translated;
      }
      const elements = root instanceof Element ? [root, ...Array.from(root.querySelectorAll("*"))] : root instanceof Document ? [root.documentElement, ...Array.from(root.querySelectorAll("*"))] : [];
      for (const element of elements) {
        if (element.closest("[data-no-translate]")) continue;
        const states = attributeText.get(element) || new Map<string, { original: string; translated: string }>();
        for (const key of ["placeholder", "title", "aria-label"]) {
          const current = element.getAttribute(key);
          if (current === null) continue;
          const prior = states.get(key);
          const original = prior && current === prior.translated ? prior.original : current;
          const translated = translate(original, language);
          states.set(key, { original, translated });
          if (translated !== current) element.setAttribute(key, translated);
        }
        attributeText.set(element, states);
      }
    };
    const target = document.getElementById("root") || document.body;
    apply(target);
    const observer = new MutationObserver(records => {
      for (const record of records) {
        if (record.type === "characterData" && record.target instanceof Text) apply(record.target.parentNode || target);
        else for (const added of Array.from(record.addedNodes)) apply(added);
        if (record.type === "attributes" && record.target instanceof Element) apply(record.target);
      }
    });
    observer.observe(target, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ["placeholder", "title", "aria-label"] });
    return () => observer.disconnect();
  }, [language]);
  return <>{children}</>;
}
